"""
OutputQualityGate — validates output is narrative, not mechanical.
Checks for tables, causal language, zone tags, founder specificity.
Zero LLM calls.
"""

import re
from dataclasses import dataclass, field


@dataclass
class QualityResult:
    passed: bool
    score: int  # 0-7, one point per check
    failures: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {"passed": self.passed, "score": self.score, "failures": self.failures}


class OutputQualityGate:
    """Validates output follows narrative intelligence format (7-point rubric)."""

    CAUSAL_MARKERS = re.compile(
        r'\b(because|causes?|leads? to|results? in|therefore|consequently|driven by|due to|mechanism)\b',
        re.IGNORECASE,
    )
    TABLE_HEADER = re.compile(r'\|\s*\w+\s*\|.*\|.*\|')  # markdown table pattern
    ZONE_TAGS = re.compile(r'\[(?:K|T|\?)\]')
    GENERIC_FILLER = re.compile(
        r'\b(consider exploring|significant potential|key stakeholders|it would be beneficial|interesting opportunity)\b',
        re.IGNORECASE,
    )

    def validate(self, output: str, require_founder_context: bool = False) -> QualityResult:
        failures: list[str] = []

        # 1. No tables in narrative sections
        narrative_section = self._extract_narrative_sections(output)
        table_rows = self.TABLE_HEADER.findall(narrative_section)
        if len(table_rows) > 2:
            failures.append(
                f"narrative_has_tables: {len(table_rows)} table rows in narrative sections"
            )

        # 2. Causal language present (≥2 markers)
        causal_matches = self.CAUSAL_MARKERS.findall(output)
        if len(causal_matches) < 2:
            failures.append(
                f"missing_causal_language: only {len(causal_matches)} causal markers found (need ≥2)"
            )

        # 3. Zone tags present inline (≥1)
        zone_matches = self.ZONE_TAGS.findall(output)
        if len(zone_matches) < 1:
            failures.append(
                f"missing_zone_tags: {len(zone_matches)} zone tags found (need ≥1)"
            )

        # 4. No generic filler phrases
        filler = self.GENERIC_FILLER.findall(output)
        if filler:
            failures.append(
                f"generic_filler: found banned phrases: {', '.join(filler[:3])}"
            )

        # 5. Has mechanism section (supports VEMRA "M —" format and "## Mechanism")
        has_mechanism = (
            "## Mechanism" in output
            or "## mechanism" in output.lower()
            or "M —" in output
            or "**M —**" in output
        )
        if not has_mechanism:
            failures.append("missing_mechanism_section")

        # 6. Has strategic path or action section
        has_path = any(
            marker in output
            for marker in (
                "## Strategic Path",
                "## Action",
                "## Execution",
                "## A —",
                "**Move",
            )
        )
        if not has_path:
            failures.append("missing_action_section")

        # 7. Founder context referenced (only when required)
        if require_founder_context:
            founder_markers = ["founder", "capital", "bootstrapper", "operator", "constraint", "profile"]
            if not any(m in output.lower() for m in founder_markers):
                failures.append("missing_founder_context")

        score = 7 - len(failures)
        return QualityResult(
            passed=score >= 5,  # must pass at least 5/7 checks
            score=score,
            failures=failures,
        )

    def _extract_narrative_sections(self, output: str) -> str:
        """Return everything except meta/footer sections (dashes + dimension lines)."""
        lines = output.split("\n")
        narrative_lines = []
        in_meta = False
        for line in lines:
            if line.startswith("---") or (line.startswith("*") and "dimensions" in line):
                in_meta = True
            elif line.startswith("## ") or line.startswith("# "):
                in_meta = False
            if not in_meta:
                narrative_lines.append(line)
        return "\n".join(narrative_lines)
